<?php require_once 'config/config.php'; require_manager();$rid=room_id();$st=db()->prepare("SELECT * FROM rooms WHERE id=?");$st->execute([$rid]);$room=$st->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='role'){ $uid=(int)$_POST['user_id'];$role=$_POST['role'];if(!in_array($role,['member','chef'],true))exit('Invalid role');db()->beginTransaction();db()->prepare("UPDATE room_members SET role=? WHERE room_id=? AND user_id=?")->execute([$role,$rid,$uid]);db()->commit();flash('Role updated.');}
elseif($action==='transfer'){ $uid=(int)$_POST['user_id'];$q=db()->prepare("SELECT 1 FROM room_members WHERE room_id=? AND user_id=? AND status='active'");$q->execute([$rid,$uid]);if(!$q->fetchColumn()){flash('Selected user is not an active member.');}else{db()->beginTransaction();db()->prepare("UPDATE room_members SET role='member' WHERE room_id=? AND role='manager'")->execute([$rid]);db()->prepare("UPDATE room_members SET role='manager' WHERE room_id=? AND user_id=?")->execute([$rid,$uid]);db()->commit();$_SESSION['user']['room_role']='member';flash('Room manager transferred.');redirect('dashboard.php');}}
elseif($action==='remove'){ $uid=(int)$_POST['user_id'];if($uid!==(int)user()['id']){db()->prepare("UPDATE room_members SET status='left' WHERE room_id=? AND user_id=?")->execute([$rid,$uid]);flash('Member removed.');}}}
$q=db()->prepare("SELECT rm.*,u.name,u.email FROM room_members rm JOIN users u ON u.id=rm.user_id WHERE rm.room_id=? AND rm.status='active' ORDER BY u.name");$q->execute([$rid]);$members=$q->fetchAll();$title='Manage room';include 'includes/header.php';?>
<div class="d-flex justify-content-between mb-4"><div><h2 class="fw-bold">Manage room</h2><p class="small-muted">Members, roles and manager transfer.</p></div><a class="btn btn-light" href="dashboard.php">Back</a></div>
<div class="row g-4"><div class="col-lg-8"><div class="card p-4"><h5 class="fw-bold">Members</h5><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Member</th><th>Role</th><th>Change</th><th>Actions</th></tr></thead><tbody><?php foreach($members as $m):?><tr><td><b><?=e($m['name'])?></b><div class="small-muted"><?=e($m['email'])?></div></td><td><?=e($m['role'])?></td><td><?php if($m['user_id']!=(int)user()['id']):?><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="role"><input type="hidden" name="user_id" value="<?=$m['user_id']?>"><select class="form-select form-select-sm" name="role"><option value="member">Member</option><option value="chef" <?=$m['role']==='chef'?'selected':''?>>Chef</option></select><button class="btn btn-sm btn-outline-dark">Save</button></form><?php endif;?></td><td><?php if($m['role']!=='manager' && $m['user_id']!=(int)user()['id']):?><form method="post" class="d-inline" data-confirm="Transfer room management to this member?"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="transfer"><input type="hidden" name="user_id" value="<?=$m['user_id']?>"><button class="btn btn-sm btn-outline-primary">Make manager</button></form> <form method="post" class="d-inline" data-confirm="Remove this member?"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="user_id" value="<?=$m['user_id']?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div>
<div class="col-lg-4"><div class="card p-4 room-access-card"><div class="d-flex justify-content-between align-items-center"><h5 class="fw-bold mb-0">Join details</h5><span class="badge badge-soft">QR + Code</span></div><div class="small-muted mt-3">Room code</div><div class="room-code-display"><?=e($room['room_code'])?></div><div class="qr-box mt-3" id="roomQrcode"></div><div class="d-grid gap-2 mt-3"><button type="button" class="btn btn-dark" id="copyRoomCode"><i class="bi bi-copy"></i> Copy room code</button><button type="button" class="btn btn-light" id="copyJoinLink"><i class="bi bi-link-45deg"></i> Copy join link</button></div><p class="small-muted mt-3 mb-0">Members can scan this QR or enter the code manually. Meal sessions: <?=$room['meal_times']?></p></div></div></div><script>const joinUrl=location.origin+location.pathname.replace('room.php','join-room.php')+'?code=<?=e($room['room_code'])?>';new QRCode(document.getElementById('roomQrcode'),{text:joinUrl,width:190,height:190});document.getElementById('copyRoomCode').addEventListener('click',async()=>{await navigator.clipboard.writeText('<?=e($room['room_code'])?>');document.getElementById('copyRoomCode').innerHTML='<i class="bi bi-check2"></i> Copied';});document.getElementById('copyJoinLink').addEventListener('click',async()=>{await navigator.clipboard.writeText(joinUrl);document.getElementById('copyJoinLink').innerHTML='<i class="bi bi-check2"></i> Link copied';});</script>
<?php include 'includes/footer.php';?>